-- HR bounded context core tables (E03-S01): department, position, employee.
-- Must run on PostgreSQL (compose) AND H2 in PostgreSQL mode (local/tests):
-- stick to the common SQL subset — UUIDs are generated by the application.

create table department (
    id          uuid primary key,
    name        varchar(100) not null,
    description varchar(500),
    created_at  timestamp with time zone not null,
    updated_at  timestamp with time zone not null,
    constraint uq_department_name unique (name)
);

create table position (
    id          uuid primary key,
    title       varchar(100) not null,
    description varchar(500),
    created_at  timestamp with time zone not null,
    updated_at  timestamp with time zone not null,
    constraint uq_position_title unique (title)
);

create table employee (
    id            uuid primary key,
    -- linked by identity onboarding (E04), never through the CRUD API
    keycloak_id   uuid,
    matricule     varchar(32)  not null,
    first_name    varchar(100) not null,
    last_name     varchar(100) not null,
    email         varchar(255) not null,
    hire_date     date         not null,
    status        varchar(20)  not null,
    manager_id    uuid,
    department_id uuid         not null,
    position_id   uuid         not null,
    created_at    timestamp with time zone not null,
    updated_at    timestamp with time zone not null,
    constraint uq_employee_matricule   unique (matricule),
    constraint uq_employee_email       unique (email),
    constraint uq_employee_keycloak_id unique (keycloak_id),
    constraint ck_employee_status      check (status in ('ACTIVE', 'DISABLED')),
    constraint fk_employee_manager     foreign key (manager_id)    references employee (id),
    constraint fk_employee_department  foreign key (department_id) references department (id),
    constraint fk_employee_position    foreign key (position_id)   references position (id)
);

create index ix_employee_manager    on employee (manager_id);
create index ix_employee_department on employee (department_id);
create index ix_employee_position   on employee (position_id);
